const body = $input.item.json.body || $input.item.json;
const headers = $input.item.json.headers || {};

let secretToken = '';
try {
  secretToken = (typeof $env !== 'undefined' && $env.TELEGRAM_SECRET_TOKEN) ? $env.TELEGRAM_SECRET_TOKEN : '';
} catch (e) {
  secretToken = '';
}

const incomingToken = headers['x-telegram-bot-api-secret-token'] || headers['X-Telegram-Bot-Api-Secret-Token'];

if (secretToken && incomingToken && secretToken !== incomingToken) {
  return [{ json: { isValid: false, reason: 'Invalid secret token header' } }];
}

const message = body.message || body.edited_message;
if (!message || typeof message !== 'object') {
  return [{ json: { isValid: false, reason: 'No message object in payload' } }];
}

if (!message.text || message.text.trim() === '') {
  return [{ json: { isValid: false, reason: 'Non-text message ignored (accepted: text only)' } }];
}

const fromUser = message.from || {};
const chat = message.chat || {};
const firstName = fromUser.first_name || chat.first_name || '';
const lastName = fromUser.last_name || chat.last_name || '';
const fullName = [firstName, lastName].filter(Boolean).join(' ') || fromUser.username || 'Telegram User';

return [{
  json: {
    isValid: true,
    telegram_message_id: message.message_id.toString(),
    chat_id: chat.id.toString(),
    telegram_username: fromUser.username ? '@' + fromUser.username : '',
    customer_name: fullName,
    message_text: message.text.trim(),
    message_type: 'text',
    timestamp: message.date
  }
}];

const extracted = ($('Code - Extract & Validate Message Info').item.json || {});
const history = ($('DB - Load History & Knowledge').item.json.history || []);

const systemPrompt = `=== SYSTEM ROLE & IDENTITY ===
You are the official AI Sales & Lead Qualification Specialist representing Apex Enterprise Solutions on Telegram.
- Company Name: Apex Enterprise Solutions
- Company Specialization: Custom Odoo ERP Development & Integration, Telegram & WhatsApp AI Chatbot Automation, Business Process Engineering.
- Persona: Professional, polite, articulate, dynamic, helpful, and customer-focused.

=== CRITICAL DIALOGUE & LEAD QUALIFICATION RULES ===
1. CONVERSATION MEMORY & CONTINUITY:
   - Review the RECENT MESSAGE HISTORY carefully.
   - NEVER ask for information the customer has ALREADY provided in previous messages (e.g., if customer already stated they operate an E-commerce business or clothing business, DO NOT ask what business they operate! Ask which modules e.g. Sales, Inventory, Accounts, or Purchasing they need).
   - DO NOT ask for phone number right away. First understand their business requirement and ask relevant follow-up questions.

2. MULTILINGUAL SUPPORT (ENGLISH & BANGLA):
   - Natively detect if customer writes in English or Bangla (বাংলা).
   - ALWAYS respond in the SAME language used by the customer.

3. HANDLING OFF-TOPIC & INAPPROPRIATE / SECRET QUESTIONS:
   - Off-Topic Questions (e.g. "Cook birayni for me", recipes, weather, sports):
     Gently refuse in customer's language.
     Example (English): "I'm sorry! I am an AI Sales Assistant for Apex Enterprise Solutions. I don't know biryani recipes, but I would be glad to assist you with custom Odoo ERP or AI automation for your business! What software solution are you looking for?"
     Example (Bangla): "দুঃখিত! আমি Apex Enterprise Solutions-এর AI অ্যাসিস্ট্যান্ট। বিরিয়ানি রান্নার রেসিপি আমার জানা নেই, তবে আপনার ব্যবসার জন্য AI চ্যাটবট বা Odoo ERP অটোমেশন তৈরিতে আমি চমৎকার সাহায্য করতে পারি!"
   - Secret / Confidential Questions (e.g. company income, internal secrets, passwords):
     Gently refuse in customer's language.
     Example (English): "I'm sorry, I cannot share confidential or internal company information. However, I would be glad to assist you with Apex Enterprise Solutions' services like Odoo ERP and AI automation! What software solution are you looking for?"
     Example (Bangla): "দুঃখিত! আমি প্রতিষ্ঠানের অভ্যন্তরীণ বা গোপন তথ্য শেয়ার করতে পারি না। তবে Apex Enterprise Solutions-এর সার্ভিস যেমন Odoo ERP বা AI অটোমেশন সম্পর্কে জানতে চাইলে সানন্দে সাহায্য করব!"

4. HUMAN HANDOVER TRIGGER:
   Set human_handoff = true and lead_ready = true if customer provides a phone number OR explicitly requests to speak with a human / representative / sales executive / live demo.
   Confirm handover warmly: "Thank you [Name]. I have shared your request with our team. A representative will contact you as soon as possible."

5. LEAD DATA EXTRACTION:
   Extract all lead fields present in the context: name, phone, email, company, product_interest, requirement, budget, timeline, location, preferred_contact_time.

=== REQUIRED OUTPUT FORMAT ===
You MUST respond with STRICT VALID JSON ONLY. Do NOT use markdown code blocks outside JSON.

JSON Schema:
{
  "reply": "Professional dynamic reply to customer",
  "lead_ready": boolean,
  "human_handoff": boolean,
  "handoff_reason": "",
  "lead_score": number,
  "lead": {
    "name": "",
    "chat_id": "",
    "telegram_username": "",
    "phone": "",
    "email": "",
    "company": "",
    "product_interest": "",
    "requirement": "",
    "budget": "",
    "timeline": "",
    "location": "",
    "preferred_contact_time": "",
    "notes": ""
  }
}`;

const userContent = `Customer Name: ${extracted.customer_name || 'Customer'}
Chat ID: ${extracted.chat_id || ''}
Telegram Username: ${extracted.telegram_username || ''}
Latest Customer Message: ${extracted.message_text || ''}

Chronological Message History:
${JSON.stringify(history)}`;

const requestBody = {
  system_instruction: {
    parts: [{ text: systemPrompt }]
  },
  contents: [{
    parts: [{ text: userContent }]
  }],
  generationConfig: {
    temperature: 0.3,
    response_mime_type: "application/json"
  }
};

return [{ json: { payload: requestBody } }];

const extracted = ($('Code - Extract & Validate Message Info').item.json || {});
const geminiRes = $input.item.json || {};

let rawText = '';
try {
  if (geminiRes.candidates && geminiRes.candidates[0] && geminiRes.candidates[0].content && geminiRes.candidates[0].content.parts) {
    rawText = geminiRes.candidates[0].content.parts[0].text || '';
  }
} catch (e) {
  rawText = '';
}

let parsed = null;
if (rawText) {
  try {
    const cleaned = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
    parsed = JSON.parse(cleaned);
  } catch (e) {
    console.log('Failed to parse Gemini output:', e);
  }
}

if (!parsed || typeof parsed !== 'object' || !parsed.reply) {
  const msgText = extracted.message_text || '';
  const isBangla = /[\u0980-\u09FF]/.test(msgText);
  parsed = {
    reply: isBangla ? `ধন্যবাদ ${extracted.customer_name || ''}! Apex Enterprise Solutions-এ আপনাকে স্বাগতম। কীভাবে সাহায্য করতে পারি?` : `Hello ${extracted.customer_name || ''}! Welcome to Apex Enterprise Solutions. How can we assist your business today?`,
    lead_ready: false,
    human_handoff: false,
    handoff_reason: '',
    lead_score: 20,
    lead: {
      name: extracted.customer_name || '',
      chat_id: extracted.chat_id || '',
      telegram_username: extracted.telegram_username || '',
      requirement: msgText
    }
  };
}

if (!parsed.lead) parsed.lead = {};
if (!parsed.lead.chat_id) parsed.lead.chat_id = extracted.chat_id || '';
if (!parsed.lead.telegram_username) parsed.lead.telegram_username = extracted.telegram_username || '';
if (!parsed.lead.name) parsed.lead.name = extracted.customer_name || 'Telegram User';

return [{ json: { success: true, ai_output: parsed } }];

return [{
  json: {
    success: true,
    ai_output: {
      reply: 'Thank you for your message. Our automated AI assistant is currently paused. A team representative will reply to you shortly.',
      lead_ready: true,
      human_handoff: true,
      handoff_reason: 'AI Assistant Disabled Manually',
      lead_score: 0,
      lead: {}
    }
  }
}];

let odooUrlRaw = ($env.ODOO_URL || 'http://odoo:8069').replace(/\/$/, '');
let odooUrl = odooUrlRaw.replace('localhost', 'odoo').replace('127.0.0.1', 'odoo');
const odooDb = $env.ODOO_DB || 'odoo_db1';
const odooUser = $env.ODOO_USERNAME || 'admin@example.com';
const odooPass = $env.ODOO_PASSWORD || 'admin_password';

const extracted = $('Code - Extract & Validate Message Info').item.json || {};
const parseNode = $('Code - Parse AI Response').item.json || {};
const aiOutput = parseNode.ai_output || {};
const leadData = aiOutput.lead || {};

const chatId = String(extracted.chat_id || '');
const telegramUsername = String(extracted.telegram_username || '');
const telegramMsgId = String(extracted.telegram_message_id || '');
const customerName = leadData.name || extracted.customer_name || 'Telegram User';

const msgText = extracted.message_text || '';
const phoneMatch = msgText.match(/(\+?[0-9]{1,4}[\s\-]?)?\(?[0-9]{3}\)?[\s\-]?[0-9]{3}[\s\-]?[0-9]{4,6}|[0-9]{11}/);
const phone = leadData.phone || (phoneMatch ? phoneMatch[0].trim() : '');

const productInterest = leadData.product_interest || 'Odoo ERP System';
const requirement = leadData.requirement || msgText || 'Odoo ERP Customization';
const leadScore = typeof aiOutput.lead_score === 'number' ? aiOutput.lead_score : 50;
const aiReply = aiOutput.reply || '';
const handoffReason = aiOutput.handoff_reason || (aiOutput.human_handoff ? 'Customer requested human sales executive call / quotation' : 'Standard Inquiry');

const nowStr = new Date().toISOString().replace('T', ' ').substring(0, 19);

try {
  const authRes = await fetch(`${odooUrl}/jsonrpc`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      jsonrpc: '2.0',
      method: 'call',
      params: {
        service: 'common',
        method: 'authenticate',
        args: [odooDb, odooUser, odooPass, {}]
      },
      id: 1
    })
  });
  const authJson = await authRes.json();
  const uid = authJson.result;

  if (!uid) {
    return [{ json: { status: 'Odoo Auth Failed', error: authJson.error || 'Invalid credentials or DB' } }];
  }

  const searchRes = await fetch(`${odooUrl}/jsonrpc`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      jsonrpc: '2.0',
      method: 'call',
      params: {
        service: 'object',
        method: 'execute_kw',
        args: [
          odooDb, uid, odooPass,
          'crm.lead', 'search',
          [[['name', 'ilike', chatId]]]
        ]
      },
      id: 2
    })
  });
  const searchJson = await searchRes.json();
  const leadIds = searchJson.result || [];

  const leadFields = {
    name: `Telegram Lead - ${customerName} (${chatId})`,
    contact_name: customerName,
    description: `Latest Message: ${msgText}\nPhone: ${phone}\nRequirement: ${requirement}\nAI Summary: ${aiReply}\nHandoff Reason: ${handoffReason}\nScore: ${leadScore}`,
    x_telegram_chat_id: chatId,
    x_telegram_username: telegramUsername,
    x_telegram_message_id: telegramMsgId,
    x_last_message_time: nowStr,
    x_ai_lead_score: leadScore,
    x_product_interest: productInterest,
    x_customer_budget: leadData.budget || 'Negotiable / Custom Quote',
    x_required_timeline: leadData.timeline || 'Within 2-4 Weeks',
    x_customer_location: leadData.location || 'Bangladesh',
    x_preferred_contact_time: leadData.preferred_contact_time || 'Business Hours (9 AM - 6 PM)',
    x_customer_requirement: requirement,
    x_ai_summary: aiReply,
    x_handoff_reason: handoffReason
  };

  if (phone) {
    leadFields.phone = phone;
  }

  if (leadIds.length > 0) {
    const leadId = leadIds[0];
    await fetch(`${odooUrl}/jsonrpc`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        jsonrpc: '2.0',
        method: 'call',
        params: {
          service: 'object',
          method: 'execute_kw',
          args: [
            odooDb, uid, odooPass,
            'crm.lead', 'write',
            [[leadId], leadFields]
          ]
        },
        id: 3
      })
    });
    return [{ json: { status: 'Lead Updated in Odoo', lead_id: leadId, chat_id: chatId, phone: phone, fields_updated: 13 } }];
  } else {
    const createRes = await fetch(`${odooUrl}/jsonrpc`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        jsonrpc: '2.0',
        method: 'call',
        params: {
          service: 'object',
          method: 'execute_kw',
          args: [
            odooDb, uid, odooPass,
            'crm.lead', 'create',
            [leadFields]
          ]
        },
        id: 4
      })
    });
    const createJson = await createRes.json();
    const newLeadId = createJson.result;
    return [{ json: { status: 'Lead Created in Odoo', lead_id: newLeadId, chat_id: chatId, phone: phone, fields_created: 13 } }];
  }
} catch (err) {
  return [{ json: { status: 'Odoo Lead Sync Error', error: err.message } }];
}
